export const QUESTIONS = [{"id":"past-2-63-2023-18","bank":"past","category":"urticaria-anaphylaxis","title":"2023년 18번","stem":"46세 여자가 그림과 같은 피부 병변이 1년 넘게 생\n긴다고 호소하였다. 인근 병원에서 H1 항히스타민제 3종\n류를 3달 이상 복용했으나 호전이 되지 않았다. 추가로\n투여할 약물은?\n① anti-IL4 monoclonal antibody\n② anti-IL5 monoclonal antibody\n③ anti-IL13 monoclonal antibody\n④ anti-IgE monoclonal antibody\n⑤ anti-IgG monoclonal antibody","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2023-18-0.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":18,"source":"감염과 면역 족보_119.pdf · 2023년 18번 · PDF 40쪽 · 답안 63쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","18","기출"],"answerStatus":"source"},{"id":"past-2-63-2023-44","bank":"past","category":"urticaria-anaphylaxis","title":"2023년 44번","stem":"24세 남자가 코로나 1차 백신을 맞고 나서 수시간\n후 두드러기가 발생하여 병원에 왔다. 몸통에 가려움을\n동반한 팽진이 수십개 관찰되었다. 평소 눌리는 자리의\n간지러움을 경험하곤 한다. 두드러기 발생에 관여한 세포\n와 의심되는 발생기전은?\n① 호산구, IgE 매개 면역반응\n② 호산구, Th2 세포활성화 반응\n③ 비만세포, IgE 매개 면역반응\n④ 호산구, 직접자극에 의한 비면역반응\n⑤ 비만세포, 직접자극에 의한 비면역반응","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2023-44-0.webp","./data/past-images/past-2-63-2023-44-1.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":44,"source":"감염과 면역 족보_119.pdf · 2023년 44번 · PDF 40쪽 · 답안 63쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","44","기출"],"answerStatus":"source"},{"id":"past-2-63-2023-47","bank":"past","category":"urticaria-anaphylaxis","title":"2023년 47번","stem":"42세 남자가 골수염으로 4주 전부터\ncephalosporin 항생제를 투여 중이다. 3일 전 38.2도\n발열을 동반한 전신 발진이 시작되었고, 편도선이 붓기\n시작하여 목통증을 호소하였다. 발진은 심하게 가려웠고\n목 주변의 임파선 결절이 만져졌다. 혈액검사 소견은 아\n래와 같다. 혈압은 140/85 mmHg, 맥박수 95회/ 분,\n호흡수 20회/분, 체온은 38.3°C였다. 다음 답가지 중\n환자의 증상을 일으키는 병태생리에 중요한 effector\ncell'과 이에 대한 적절한 치료' 가 바르게 조합된 것은?\n① Mast cell - antihistamine\n② Mast cell - systemic steroids\n③ NK T cell - iv immunoglobulin\n④ Eosinophil - systemic steroids\n⑤ Neutrophil systemic steroids","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2023-47-0.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":47,"source":"감염과 면역 족보_119.pdf · 2023년 47번 · PDF 41쪽 · 답안 63쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","47","기출"],"answerStatus":"source"},{"id":"past-2-63-2022-47","bank":"past","category":"urticaria-anaphylaxis","title":"2022년 47번","stem":"55세 남자가 호흡곤란을 호소하며 실신하여 응급실\n로 이송되었다. 기저질환인\n간세포암을 추적관찰하기 위하여 복부 CT를 촬영한 뒤에\n귀가준비를 하던 중 전신의\n가려움증이 시작되었다. 이후 1-2분 내로 급격하게 호흡\n곤란이 진행하여 의료진에게\n도움을 청하려던 중에 의식을 잃고 쓰러졌다.\n다음 중 환자의 증상 발생 기전에 관여하는 것으로 추정\n가능하지 않은 물질은?\n① IgE\n② Fcε RI\n③ histamine\n④ C3a\n⑤ C1 esterase inhibitor","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2022-47-0.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":47,"source":"감염과 면역 족보_119.pdf · 2022년 47번 · PDF 41쪽 · 답안 63쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","47","기출"],"answerStatus":"source"},{"id":"past-2-63-2022-49","bank":"past","category":"urticaria-anaphylaxis","title":"2022년 49번","stem":"페니실린 주사 직후 나타난 아나필락시스, 새우 섭\n취 직후 나타난 두드러기, 꽃가루 흡입 직후 나타난 콧물\n에서 공통적으로 관여하는 면역세포는?\n① 호산구(eosinophil)\n② 호중구(neutrophil)\n③ 비만세포(mast cell)\n④ 대식세포(macrophage)\n⑤ 수지상세포(dendritic cell)","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2022-49-0.webp","./data/past-images/past-2-63-2022-49-1.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":49,"source":"감염과 면역 족보_119.pdf · 2022년 49번 · PDF 41쪽 · 답안 63쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","49","기출"],"answerStatus":"source"},{"id":"past-2-63-2022-58","bank":"past","category":"urticaria-anaphylaxis","title":"2022년 58번","stem":"32세 남자가 반복되는 입술 혈관부종으로 내원하였\n다. 두드러기는 동반되지 않는다고 하였다. Kallikrein-\nkinin system의 하위 pathway에 작용하여 혈관부종을\n유발할 수 있어 환자에게 복용력을 확인해야 하는 약제\n는 다음 중 무엇인가?\n① NSAIDs (nonsteroidal anti-inflammatory drugs)\n② Clopidogrel\n③ ACEI (angiotensin converting enzyme inhibitor)\n④ Cephalosporin계 항생제\n⑤ Icatibant (bradykinin antagonist)","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2022-58-0.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":58,"source":"감염과 면역 족보_119.pdf · 2022년 58번 · PDF 41쪽 · 답안 63쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","58","기출"],"answerStatus":"source"},{"id":"past-2-63-2022-59","bank":"past","category":"urticaria-anaphylaxis","title":"2022년 59번","stem":"56세 남자가 복부 조영증강 컴퓨터단층촬영을 하던\n중 갑자기 호흡곤란과 어지러움증을 호소하였다. 혈압\n90/60 mmHg, 맥박 110회/분, 호흡 32회/분, 체온\n36.9℃, 산소포화도 86%이었다. 전신에 붉은 발적이 있\n었고 전폐야에서 천명음이 들렸다. 2년 전 심혈관조영술\n후에도 전신 두드러기가 발생한 적이 있었다. 가장 먼저\n시행해야 하는 치료법은?\n① 조영제 탈감작치료\n② 에피네프린 근육주사\n③ 스테로이드제 정맥주사\n④ 항히스타민제 정맥주사\n⑤ 속효성 베타2항진제 흡입치료","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2022-59-0.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":59,"source":"감염과 면역 족보_119.pdf · 2022년 59번 · PDF 41쪽 · 답안 63쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","59","기출"],"answerStatus":"source"},{"id":"past-2-63-2022-63","bank":"past","category":"urticaria-anaphylaxis","title":"2022년 63번","stem":"18세 남자가 아나필락시스로 병원에 왔다. 평소 문\n제없이 즐겨먹던 피자를 점심으로 먹고 바로 농구를 하\n던 중에 전신 두드러기와 호흡곤란이 발생하였다고 한다.\n평소 농구도 문제없이 즐겨하였다고 한다. 다음 중 진단\n에 도움이 되는 검사는?\n① serum C3/C4\n② serum total IgE\n③ serum omega-5 gliadin specific IgE\n④ blood eosinophil count\n⑤ serum eosinophilic cationic protein","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2022-63-0.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":63,"source":"감염과 면역 족보_119.pdf · 2022년 63번 · PDF 41쪽 · 답안 63쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","63","기출"],"answerStatus":"source"},{"id":"past-2-63-2021-27","bank":"past","category":"urticaria-anaphylaxis","title":"2021년 27번","stem":"다음 중 Rapid desensitization의 가장 좋은 적응\n증은?\n① 피부묘기증을 동반한 만성 두드러기 환자\n② 땅콩 섭취 후 아나필락시스를 경험한 환자\n③ 구리 반지를 끼면 진물이 흐르는 피부 병변이 생기는\n환자\n④ 페니실린 항생제 투여가 꼭 필요하지만 10년 전 투여\n후 아나필락시스를 경험한 환자\n⑤ 혈압강하제인 angiotensin converting enzyme\ninhibitor 섭취 후 혈관 부종이 생긴 환자","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2021-27-0.webp","./data/past-images/past-2-63-2021-27-1.webp"],"choiceLabelsOnly":true,"year":2021,"originalNumber":27,"source":"감염과 면역 족보_119.pdf · 2021년 27번 · PDF 41쪽 · 답안 63쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2021","27","기출"],"answerStatus":"source"},{"id":"past-2-63-2021-28","bank":"past","category":"urticaria-anaphylaxis","title":"2021년 28번","stem":"만성 두드러기 발생에서 자가 면역 기전을 확인해보\n기 위해 시행하는 검사는?\n① Ice cube test\n② Allergen patch test\n③ Methacholine skin test\n④ Complement fixation test\n⑤ Autologous serum skin test","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2021-28-0.webp"],"choiceLabelsOnly":true,"year":2021,"originalNumber":28,"source":"감염과 면역 족보_119.pdf · 2021년 28번 · PDF 42쪽 · 답안 63쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2021","28","기출"],"answerStatus":"source"},{"id":"past-2-63-2021-29","bank":"past","category":"urticaria-anaphylaxis","title":"2021년 29번","stem":"페니실린 주사 직후 나타난 아나필락시스, 새우 섭\n취 직후 나타난 두드러기, 꽃가루 흡입 직후 나타난 콧물\n의 증상 발생에 공통적으로 관여하는 면역세포는?\n① 호산구(eosinophil)\n② 호중구(neutrophil)\n③ 비만세포(mast cell)\n④ 대식세포(macrophage)\n⑤ 수지상세포(dendritic cell)","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2021-29-0.webp"],"choiceLabelsOnly":true,"year":2021,"originalNumber":29,"source":"감염과 면역 족보_119.pdf · 2021년 29번 · PDF 42쪽 · 답안 63쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2021","29","기출"],"answerStatus":"source"},{"id":"past-2-63-2020-31","bank":"past","category":"urticaria-anaphylaxis","title":"2020년 31번","stem":"29세 여자 산모가 분만실에서 갑자기 혈압저하와 함\n께 의식을 잃었다. 증상은 담당의사가 내진을 한 직후에\n생겼다. 혈압 55/32 mmHg, 맥박 115회/분, 호흡 40\n회/분, 체온 36.5도였다. 직업은 간호사였으며 평소 장\n갑을 끼면 손에 발적이 생겨서 안쪽에 비닐장갑을 낀 후\n장갑을 착용했다고 한다. 가장 먼저 투여해야 하는 약물\n은?\n① 아세틸콜린\n② 에피네프린\n③ 항히스타민제\n④ 항류코트리엔제\n⑤ 부신피질스테로이드","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2020-31-0.webp","./data/past-images/past-2-63-2020-31-1.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":31,"source":"감염과 면역 족보_119.pdf · 2020년 31번 · PDF 42쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","31","기출"],"answerStatus":"source"},{"id":"past-2-63-2020-32","bank":"past","category":"urticaria-anaphylaxis","title":"2020년 32번","stem":"25세 남자가 여름에 달리기를 하거나 사우나에 가면\n1-2mm의 발진이 전신에 광범위하게 생긴다고 한다. 진\n단은?\n① 열 두드러기\n② 일광 두드러기\n③ 한랭 두드러기\n④ 콜린성 두드러기\n⑤ 음식의존 운동유발 아나필락시스","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2020-32-0.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":32,"source":"감염과 면역 족보_119.pdf · 2020년 32번 · PDF 42쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","32","기출"],"answerStatus":"source"},{"id":"past-2-63-2020-33","bank":"past","category":"urticaria-anaphylaxis","title":"2020년 33번","stem":"32세 여자가 지속적으로 얼굴이 붓는 증상으로 병원\n에 왔다. 13년 전부터 일년에 서너번씩 눈꺼풀이 부었고,\n때로는 손이나 발 한쪽이 부었다. 복통이 동반되기도 하\n였다. 특별한 유발요인은 없었는데, 감별진단을 위해 추\n가로 물어보아야 할 병력은?\n① 천식\n② 두드러기\n③ 알레르기비염\n④ 아나필락시스\n⑤ 음식 알레르기","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-63-2020-33-0.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":33,"source":"감염과 면역 족보_119.pdf · 2020년 33번 · PDF 42쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","33","기출"],"answerStatus":"source"},{"id":"past-2-66-2025-11","bank":"past","category":"other-allergic-disorders","title":"2025년 11번","stem":"12세 여아가 비행기 안에서 다른 승객이 땅콩 스낵\n을 먹은 후 갑작기 얼굴이 부으면서 호흡곤란을 일으켰\n다. 기내 응급키트로 구비된 epinephrine 주사를 맞은\n후 증상이 일부 개선되었다. 반응이 발생한 주요 기전은?\n① 땅콩항원에 의한 C5a 매개 비만세포 활성화\n② 땅콩항원에 의한 ILC2 활성화에 따른 기관지 수축\n③ 땅콩항원 특이 IgE 교차결합에 의한 비만세포 활성화\n④ 땅콩항원에 의한 TLR4 매개 비만세포 활성화\n⑤ 땅콩항원에 의한 기억 Th2세포 활성화","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2025-11-0.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":11,"source":"감염과 면역 족보_119.pdf · 2025년 11번 · PDF 42쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","11","기출"],"answerStatus":"source"},{"id":"past-2-66-2025-45","bank":"past","category":"other-allergic-disorders","title":"2025년 45번","stem":"36세 남자가 1년 전부터 반복되는 호흡곤란, 기침,\n열감으로 병원에 왔다. 2년 전부터  연구소에서 동물 실\n험을 하고 있으며, 증상은 동물 실험할 때 심해지고 일을\n쉬는 주말에 호전되었다. 진단을 위해 환자 혈청으로 다\n음 검사를 시행하였다. 발병 기전은?\n① 호산구 침윤\n② 보체 활성화\n③ 면역복합체 생성\n④ 기도 내 억제T림프구 감소\n⑤ 밀가루 특이 면역글로불린E 매개","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2025-45-0.webp","./data/past-images/past-2-66-2025-45-1.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":45,"source":"감염과 면역 족보_119.pdf · 2025년 45번 · PDF 42쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","45","기출"],"answerStatus":"source"},{"id":"past-2-66-2025-51","bank":"past","category":"other-allergic-disorders","title":"2025년 51번","stem":"다음 그림에서 붉은색 알레르겐 성분에 대한 특이\n면역글로불린E 로 설명할 수 있는 증상은?\n① 우유 섭취 후 복통 환자에서 치즈 섭취 후 구역감\n② 빵 섭취 후 아나필락시스 환자에서 피자 섭취 후\n두드러기\n③ 복숭아 섭취 후 두드러기 환자에서 구리 반지 끼고\n두드러기\n④ 자작나무 꽃가루 알레르기 비염 환자에서 사과 섭취\n후 입술부종\n⑤ 페니실린 주사 후 두드러기 환자에서 세팔로스포린\n주사 후 아나필락시스","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2025-51-0.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":51,"source":"감염과 면역 족보_119.pdf · 2025년 51번 · PDF 43쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","51","기출"],"answerStatus":"source"},{"id":"past-2-66-2023-16","bank":"past","category":"other-allergic-disorders","title":"2023년 16번","stem":"25 세 남자가 라면을 먹고 탁구를 치다가 숨이 차고,\n어지럼증, 복통이 생겨서 응급실에 왔다. 혈압 80/50\nmmHg, 맥박 130 회/분, 호흡 28 회/분, 체온\n36.5°C 였다. 전신에 두드러기가 관찰되었다. 평소 탁\n구를 즐겨 치는데, 이 전에도 점심 식사 후 탁구를\n치다가 유사한 반응을 두 번 경험하였다. 발생 기전은?\n① 보체 매개\n② 면역글로불린E 매개\n③ 직접적인 비만세포자극\n④ 브라기키닌(Bradykinin) 매개\n⑤ 아라키돈산(Arachidonic acid) 대사 변형","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2023-16-0.webp","./data/past-images/past-2-66-2023-16-1.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":16,"source":"감염과 면역 족보_119.pdf · 2023년 16번 · PDF 43쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","16","기출"],"answerStatus":"source"},{"id":"past-2-66-2023-24","bank":"past","category":"other-allergic-disorders","title":"2023년 24번","stem":"36세 남자가 1년 전부터 반복되는 호흡곤란, 기침,\n열감으로 병원에 왔다. 2년 전부터 연구소에서 동물 실험\n을 하고 있으며, 증상은 동물 실험할 때 심해지고 일을\n쉬는 주말에 호전되었다. 진단을 위해 환자 혈청으로 다\n음 검사를 시행하였다. 발생 기전은?\n① 호산구 침윤\n② 보체 활성화\n③ 면역복합체 생성\n④ 기도 내 억제T림프구 감소\n⑤ 밀가루 특이 면역글로불린E 매개","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2023-24-0.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":24,"source":"감염과 면역 족보_119.pdf · 2023년 24번 · PDF 43쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","24","기출"],"answerStatus":"source"},{"id":"past-2-66-2023-29","bank":"past","category":"other-allergic-disorders","title":"2023년 29번","stem":"다음 그림은 알레르기 질환의 원인 알레르겐을 찾기\n위한 검사이다. 이 검사가 진단에 가장 도움이 되는 환자\n는?\n① 찬바람에 노출되자마자 발생한 기침\n② 옻나무 접촉 다음날 발생한 접촉 부위 습진\n③ 메타콜린기관지유발검사 도중 발생한 호흡곤란\n④ 사과 섭취 5분 후 발생한 두드러기와 입술 부종\n⑤ 밀가루 음식을 섭취하면 반복적으로 발생하는 혈변","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2023-29-0.webp","./data/past-images/past-2-66-2023-29-1.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":29,"source":"감염과 면역 족보_119.pdf · 2023년 29번 · PDF 43쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","29","기출"],"answerStatus":"source"},{"id":"past-2-66-2023-45","bank":"past","category":"other-allergic-disorders","title":"2023년 45번","stem":"붉은색 알레르겐 성분에 대한 특이 IgE로 설명할 수\n있는 증상은?\n① 우유 섭취 후 복통 환자에서 치즈 섭취 후 구역감\n② 빵 섭취 후 아나필락시스 환자에서 피자 섭취 후 두\n드러기\n③ 복숭아 섭취 후 두드러기 환자에서 구리 반지 끼고\n두드러기\n④ 자작나무 꽃가루 알레르기 비염 환자에서 사과 섭취\n후 두드러기\n⑤ 페니실린 주사 후 두드러기 환자에서 세팔로스포린\n주사 후 두드러기","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2023-45-0.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":45,"source":"감염과 면역 족보_119.pdf · 2023년 45번 · PDF 44쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","45","기출"],"answerStatus":"source"},{"id":"past-2-66-2022-11","bank":"past","category":"other-allergic-disorders","title":"2022년 11번","stem":"다음 그림은 알레르기 질환의 원인 알레르겐을 찾기\n위한 검사이다. 이 검사가 진단에 가장 도움이 되는 환자\n는?\n① 찬바람을 쏘이면 즉시 발생한 기침\n② 옻나무 접촉 다음날 발생한 접촉 부위 습진\n③ 메타콜린기관지유발검사 도중 발생한 호흡곤란\n④ 사과 섭취 5분 후 발생한 두드러기와 입술 부종\n⑤ 밀가루 음식을 섭취하면 반복적으로 발생한 혈변","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2022-11-0.webp","./data/past-images/past-2-66-2022-11-1.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":11,"source":"감염과 면역 족보_119.pdf · 2022년 11번 · PDF 44쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","11","기출"],"answerStatus":"source"},{"id":"past-2-66-2022-15","bank":"past","category":"other-allergic-disorders","title":"2022년 15번","stem":"47세 남자가 수개월 전부터 발생한 호흡곤란으로 왔\n다. 5년 전부터 버섯재배 농장에서 근무하고 있었으며,\n버섯 창고에 다녀오면 2-3시간 지나 발열, 기침, 피로\n감, 근육통과 함께 호흡곤란이 심해졌다. 청진 상 양측\n폐하부에서 수포음이 들렸고, 가슴 CT 소견은 다음과 같\n다. 기관지폐포세척액에서 가장 증가되어 있을 것으로 예\n상되는 면역세포는?\n① 대식세포\n② 림프구\n③ 호산구\n④ 호중구\n⑤ 형질세포","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2022-15-0.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":15,"source":"감염과 면역 족보_119.pdf · 2022년 15번 · PDF 44쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","15","기출"],"answerStatus":"source"},{"id":"past-2-66-2022-17","bank":"past","category":"other-allergic-disorders","title":"2022년 17번","stem":"20세 여자가 6개월 전부터 사과를 먹으면 입이 붓고\n가려움이 있어 왔다. 사과를 먹으면 수분 내로 증상이 생\n겼고 20-30분 정도 지나 호전되나 때로는 목이 붓기도\n하였다. 2년 전부터 봄철에 콧물, 재채기, 눈가려움이 있\n다. 상용화된 시약을 이용한 음식물 피부반응검사에서는\n사과에 음성으로 다른 검사를 통해 확인해 보려 한다. 적\n절한 검사는?\n① basophil activation test\n② intradermal skin test\n③ patch test\n④ prick to prick test\n⑤ specific IgG4 test","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2022-17-0.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":17,"source":"감염과 면역 족보_119.pdf · 2022년 17번 · PDF 44쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","17","기출"],"answerStatus":"source"},{"id":"past-2-66-2022-32","bank":"past","category":"other-allergic-disorders","title":"2022년 32번","stem":"24세 남자가 피자를 먹고 조깅하던 중 갑작스런 전\n신두드러기와 의식소실로 응급실에 왔다. 내원시 혈압은\n80/50 mmHg, 심박수 110회, 호흡수 24회로 에피네프\n린 투약 후 호전되었다. 6개월 전에도 짜장면을 먹고 농\n구하던 중 두드러기와 얼굴부종, 호흡곤란이 있었던 적이\n있다. 원인 확진 검사는?\n① 운동유발검사\n② 음식물 피부반응검사\n③ 밀가루 경구유발시험\n④ 밀가루 특이 IgE 항체 검사\n⑤ 밀가루 섭취 후 운동유발시험","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2022-32-0.webp","./data/past-images/past-2-66-2022-32-1.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":32,"source":"감염과 면역 족보_119.pdf · 2022년 32번 · PDF 44쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","32","기출"],"answerStatus":"source"},{"id":"past-2-66-2021-36","bank":"past","category":"other-allergic-disorders","title":"2021년 36번","stem":"45세 남자가 벌에 쏘인 후 호흡곤란과 의식소실로\n응급실에 왔다. 환자는 이전에도 벌에 쏘였을 때 전신에\n두드러기와 어지러움이 있었던 적이 있었고 골프장 조경\n을 담당하고 있어 직업상 벌에 쏘일 위험이 많다. 예방을\n위한 적절한 치료는 ?\n① 면역글로불린 주사\n② 벌독을 이용한 면역치료\n③ 야외 활동 전 항히스타민제 복약\n④ 야외 활동 전 스테로이드제 복약\n⑤ 항 IgE 항체치료제 주사","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2021-36-0.webp"],"choiceLabelsOnly":true,"year":2021,"originalNumber":36,"source":"감염과 면역 족보_119.pdf · 2021년 36번 · PDF 45쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2021","36","기출"],"answerStatus":"source"},{"id":"past-2-66-2021-48","bank":"past","category":"other-allergic-disorders","title":"2021년 48번","stem":"23세 남자가 새우를 먹고 15분 만에 전신 두드러기\n와 입술 부종으로 응급실에 내원하였다. 어지러움과 호흡\n곤란을 호소하였고 전 폐야에서 천명음이 들렸다. 혈압\n70/40 mmHg, 맥박 135회/분, 호흡 24회/분 체온\n36.0도였다. 회복 후 새우와 증상의 관련성 확인을 위해\n시행해 볼 수 있는 방법은?\n① 음식물일기\n② 혈중 Tryptase 검사\n③ 이중맹검 새우 경구유발시험\n④ 혈중 새우 항원 특이 IgE 검사\n⑤ 새우 항원을 이용한 피내 피부 반응 검사","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2021-48-0.webp"],"choiceLabelsOnly":true,"year":2021,"originalNumber":48,"source":"감염과 면역 족보_119.pdf · 2021년 48번 · PDF 45쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2021","48","기출"],"answerStatus":"source"},{"id":"past-2-66-2020-43","bank":"past","category":"other-allergic-disorders","title":"2020년 43번","stem":"27세 남성이 새우를 먹고 복통과 두드러기가 반복되\n어 내원하였다. 새우를 섭취하고 10분만에 증상이 나타\n났고, 새우를 익혀먹을 때보다 날 것으로 먹을 때 증상이\n심했다고 한다. 이 환자의 진단에 대한 표준검사는?\n① Serum shrimp-specific IgE test\n② Shrimp prick to prick test\n③ Open food challange\n④ Single-blind food challenge\n⑤ Double-blind placebo-controlled food challenge","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2020-43-0.webp","./data/past-images/past-2-66-2020-43-1.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":43,"source":"감염과 면역 족보_119.pdf · 2020년 43번 · PDF 45쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","43","기출"],"answerStatus":"source"},{"id":"past-2-66-2020-44","bank":"past","category":"other-allergic-disorders","title":"2020년 44번","stem":"7개월 영아가 우유를 섭취하고 입술 주변 얼굴이 붉\n어지고 가려움을 호소하였다. 우유 섭취에 대한 알레르기\n예방을 위한 방법으로 적절한 것은?\n① 우유 대신 산양유를 섭취한다.\n② 우유 대신 가수분해 분유를 섭취한다.\n③ 음식물 알레르기는 자라면서 자연히 사라지므로 제한\n없이 계속 섭취한다.\n④ 우유에 대한 피부반응검사를 시행한 후 그 결과에 따\n라 결정한다.\n⑤ 우유 섭취 전 예방적으로 스테로이드를 복용한다.","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2020-44-0.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":44,"source":"감염과 면역 족보_119.pdf · 2020년 44번 · PDF 45쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","44","기출"],"answerStatus":"source"},{"id":"past-2-66-2020-45","bank":"past","category":"other-allergic-disorders","title":"2020년 45번","stem":"20세 남자가 1년 전부터 반복되는 피부 병변으로 병\n원에 왔다. 좁쌀 모양으로 몸통과 사지에 생기며, 땀을\n흘리며 운동을 하면 잘 생긴다. 심장이 빠르게 뛰거나 어\n지럽기도 하다. 진단은?\n① rash\n② angioedema\n③ cholinergic urticaria\n④ 두드러기성 혈관염\n⑤ 운동유발 아나필락시스","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-66-2020-45-0.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":45,"source":"감염과 면역 족보_119.pdf · 2020년 45번 · PDF 45쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","45","기출"],"answerStatus":"source"},{"id":"past-2-64-2025-7","bank":"past","category":"eosinophilic-disorders","title":"2025년 7번","stem":"45세 남자가 말초혈액의 호산구증가로 왔다. 평소 콧\n물, 재채기가 있어 항히스타민제을 자주 복약하고 있으\n며, 1주일 전 부비동염이 생겨 항생제를 복약하면서 발진\n과 가려움이 생겼다. 평소 생선회는 종종 먹으나 그 외\n날음식은 섭취하지 않으며, 검사소견은 아래와 같다. 가\n능성이 높은 호산구 증가의 원인은?\nWBC 8,950/mm3, hemoglobin 13.4 g/dL,\nplatelet 236,000/mm3,\nneutrophil 53%, eosinophil 21%\nTotal IgE: 95 IU/ml\n흡입항원 피부단자시험: 음성\n흉부 및 부비동 단순X선 검사 : 정상\n① 항생제\n② 개회충증\n③ 항히스타민제\n④ 알레르기비염\n⑤ 특발성 과호산구증가증","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":1,"acceptedAnswers":[1],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2025-7-0.webp","./data/past-images/past-2-64-2025-7-1.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":7,"source":"감염과 면역 족보_119.pdf · 2025년 7번 · PDF 45쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ①\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","7","기출"],"answerStatus":"source"},{"id":"past-2-64-2025-8","bank":"past","category":"eosinophilic-disorders","title":"2025년 8번","stem":"42세 남성이 반복적인 기침과 천명으로 병원에 왔다.\n증상 발생은 계절이나 특정 환경과 무관하게 발생했으며,\n피부바늘따끔검사와 혈청 특이 IgE 검사에서 모든 항원\n에 대해 음성반응을 보였다.\n유도객담검사 호산구 10%\n폐기능 검사 FEV1 예측치의 78%.\nTezepelumab (anti-TSLP)을 투여한 후 증상과 FEV1\n(92%)이 호전되었다. 이 환자의 호산구성 기도 염증을\n유발하는 핵심 면역세포는?\n① Type 2 innate lymphoid cell\n② Type 3 innate lymphoid cell\n③ NK cell\n④ Th2 cell\n⑤ Alveolar macrophage","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":1,"acceptedAnswers":[1],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2025-8-0.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":8,"source":"감염과 면역 족보_119.pdf · 2025년 8번 · PDF 46쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ①\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","8","기출"],"answerStatus":"source"},{"id":"past-2-64-2025-9","bank":"past","category":"eosinophilic-disorders","title":"2025년 9번","stem":"54세 여자가 호흡곤란으로 왔다. 최근 2달 전부터 전\n신쇠약감과 함께 기침을 동반하였으며, 혈액검사 소견에\n서 WBC 34,720/mm3 (eosinophil 52%), AST/ALT\n158/230 IU/L 이었고, 흉부 X선 검사 상 양 폐야의 침\n윤이 관찰되었다. 골수검사를 시행하였고, F1P1L1-\nPDGFRA 유전자 변이가 확인되었다. 적절한 치료제는?\n① Imatinib\n② Cyclosporin\n③ Mepolizumab\n④ Corticosteroid\n⑤ Interferon alpha","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":1,"acceptedAnswers":[1],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2025-9-0.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":9,"source":"감염과 면역 족보_119.pdf · 2025년 9번 · PDF 46쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ①\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","9","기출"],"answerStatus":"source"},{"id":"past-2-64-2025-10","bank":"past","category":"eosinophilic-disorders","title":"2025년 10번","stem":"다음 중 호산구의 생성, 분화, 활성화와 관련된 싸이\n토카인 (A)과 활성화된 호산구의 과립에서 분비되어 기\n생충에 대한 방어와 조직 손상에 관여하는 단백 (B)의\n조합으로 적절한 것은?\n① IL-3 / eotaxin\n② IL-5 / major basic protein\n③ IL-10 / eosinophil peroxidase\n④ IL-13 / eosinophil cationic protein\n⑤ IL-17 / prostaglandin E2","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2025-10-0.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":10,"source":"감염과 면역 족보_119.pdf · 2025년 10번 · PDF 46쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","10","기출"],"answerStatus":"source"},{"id":"past-2-64-2023-22","bank":"past","category":"eosinophilic-disorders","title":"2023년 22번","stem":"48세 여자가 호흡곤란으로 왔다. 최근 2달 전부터\n전신쇠약감과 함께 기침을 동반하였으며, 혈액검사 소견\n에서 WBC 21,340/mm2 (eosinophil 53%), AST/ALT\n160/220 IU/L 이었고, 흉부 X선 검사 상 양 폐야의 침\n윤이 관찰되었다. 골수검사를 시행하였고, F1P1L1-\nPDGFRA 유전자 변이가 확인되었다. 적절한 치료제는?\n① Corticosteroid\n② Cyclosporin\n③ Imatinib\n④ Interferon alpha\n⑤ Mepolizumab","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2023-22-0.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":22,"source":"감염과 면역 족보_119.pdf · 2023년 22번 · PDF 46쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","22","기출"],"answerStatus":"source"},{"id":"past-2-64-2023-32","bank":"past","category":"eosinophilic-disorders","title":"2023년 32번","stem":"52세 남자가 혈액검사의 이상소견으로 왔다. WBC\n11,530/mm2, hemoglobin 13.1 g/dL, platelet\n209,000/mm2, neutrophil 47%, eosinophil 28%,\nIgE 580 IU/mL, AST/ALT 63/92 IU/L 였고, 6개월 전\n혈 액검사 소견은 정상이었다. 봄, 가을에 악화되는 알레\n르기비염이 있어 간헐적으로 항히스타민제를 복약 중이\n며, 한달 전 생간과 내장을 날로 섭취한 적이 있다. 호산\n구증가의 원인 진단은?\n① Toxocariasis\n② Allergic rhinitis\n③ Hypereosinophilic syndrome\n④ Eosinophilic granulomatous polyangiitis\n⑤ Drug rash with eosinophilia and systemic\nsymptoms","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":1,"acceptedAnswers":[1],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2023-32-0.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":32,"source":"감염과 면역 족보_119.pdf · 2023년 32번 · PDF 46쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ①\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","32","기출"],"answerStatus":"source"},{"id":"past-2-64-2023-38","bank":"past","category":"eosinophilic-disorders","title":"2023년 38번","stem":"다음 중 호산구의 생성, 분화, 활성화와 관련된 싸이\n토카인 (A)와 조직으로의 화학주성과 관련된 케모카인\n(B)의 조합으로 적절한 것은?\n① IL-3 / CCL2\n② IL-5 / CCL11\n③ IL-8 / CCL17\n④ IL-10 / CCL22\n⑤ IL-17 / CCL26","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2023-38-0.webp","./data/past-images/past-2-64-2023-38-1.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":38,"source":"감염과 면역 족보_119.pdf · 2023년 38번 · PDF 46쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","38","기출"],"answerStatus":"source"},{"id":"past-2-64-2023-50","bank":"past","category":"eosinophilic-disorders","title":"2023년 50번","stem":"37세 여자가 건강검진 혈액검사에서 호산구가\n1,200/mm2, 총 면역글로불린 E가 150 kU/L였다. 알\n레르기 피부단자 검사에서는 양성을 보인 항원은 없었다.\n특별히 불편감을 호소하지는 않았다. 체내에 증가 되어\n있을 가능성이 큰 사이토카인은?\n① Interleukin-1\n② Interleukin-5\n③ Interferon-y\n④ Interleukin-12\n⑤ Interleukin-17","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":1,"acceptedAnswers":[1],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2023-50-0.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":50,"source":"감염과 면역 족보_119.pdf · 2023년 50번 · PDF 47쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ①\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","50","기출"],"answerStatus":"source"},{"id":"past-2-64-2022-13","bank":"past","category":"eosinophilic-disorders","title":"2022년 13번","stem":"다음 중 clonal eosinophilia 발병 기전에 기초하여\n사용할 수 있는 호산구성 질환 치료제는?\n① Steroid\n② Imatinib\n③ Hydroxyurea\n④ Mepolizumab\n⑤ Interferon alpha","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2022-13-0.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":13,"source":"감염과 면역 족보_119.pdf · 2022년 13번 · PDF 47쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","13","기출"],"answerStatus":"source"},{"id":"past-2-64-2022-21","bank":"past","category":"eosinophilic-disorders","title":"2022년 21번","stem":"65세 여자가 건강 검진 시 우연히 발견한 흉부 방사\n선 이상으로 내원하였다(사진 1). 발열, 기침, 가래 등 특\n별한 증상을 호소하지는 않았으며 검사 상 말초 혈액 호\n산구 수치가 4,600/ul로 증가된 것 이외 다른 이상은 찾\n지 못하였다. 평소 민물 게장을 즐겨 섭취한 과거력이 있\n었다. 사진 2는 별다른 치료없이 1달 뒤에 촬영한 흉부\n방사선이다. 가장 가능성이 큰 진단은?\n① Asthma\n② Hypereosinophilic syndrome\n③ Acute eosinophilic pneumonia\n④ Allergic bronchopulmonary aspergillosis\n⑤ Helminthic infection-related eosinophilic lung\ndisease","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2022-21-0.webp","./data/past-images/past-2-64-2022-21-1.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":21,"source":"감염과 면역 족보_119.pdf · 2022년 21번 · PDF 47쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","21","기출"],"answerStatus":"source"},{"id":"past-2-64-2022-31","bank":"past","category":"eosinophilic-disorders","title":"2022년 31번","stem":"최근 비알레르기성 호산구 증가로 인한 천식 발생\n기전이 새롭게 규명되고 있다. 비특이적 자극을 받아 기\n도 상피에서 분비되고 innate lymphocyte를 활성화시키\n는 사이토카인 A는?\n① IL-5\n② IL-10\n③ IL-18\n④ IL-25\n⑤ IL-35","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2022-31-0.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":31,"source":"감염과 면역 족보_119.pdf · 2022년 31번 · PDF 47쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","31","기출"],"answerStatus":"source"},{"id":"past-2-64-2021-32","bank":"past","category":"eosinophilic-disorders","title":"2021년 32번","stem":"호산구의 분화와 증식에 중요한 역할을 하여 최근\n개발된 호산구성 질환 치료제의 타겟이 되는 싸이토카인\n은?\n① IL-3\n② IL-5\n③ IL-33\n④ TSLP\n⑤ GM-CSF","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2021-32-0.webp","./data/past-images/past-2-64-2021-32-1.webp"],"choiceLabelsOnly":true,"year":2021,"originalNumber":32,"source":"감염과 면역 족보_119.pdf · 2021년 32번 · PDF 47쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2021","32","기출"],"answerStatus":"source"},{"id":"past-2-64-2021-34","bank":"past","category":"eosinophilic-disorders","title":"2021년 34번","stem":"다음 중 clonal eosinophilia 발병 기전에 기초하여\n사용할 수 있는 효과적인 치료제는?\n① Interferon alpha\n② Mepolizumab\n③ Hydroxyurea\n④ Imatinib\n⑤ Steroid","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2021-34-0.webp"],"choiceLabelsOnly":true,"year":2021,"originalNumber":34,"source":"감염과 면역 족보_119.pdf · 2021년 34번 · PDF 48쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2021","34","기출"],"answerStatus":"source"},{"id":"past-2-64-2021-35","bank":"past","category":"eosinophilic-disorders","title":"2021년 35번","stem":"65세 남자가 우측 발 처짐과 이상 감각으로 내원하\n였다. 증상은 8개월 전부터 지속되었으며 6개월전 시행\n한 외부 병원검사 상 말초 혈액 호산구 수치가 8600/ul\n로 증가된 것 이외 다른 이상은 찾지 못하였다. 금일 검\n사한 말초 혈액 호산구 수치도 7200/ul으로 증가되어있\n었다. 병력 청취 상 호산구를 증가시킬 수 있는 2차적인\n원인은 불분명하였다. 가장 가능성이 큰 진단은?\n① Allergic bronchopulmonary aspergillosis\n② Chronic eosinophilic pneumonia\n③ Eosinophilia myalgia syndrome\n④ Hypereosinophilic syndrome\n⑤ Eosinophilic leukemia","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2021-35-0.webp"],"choiceLabelsOnly":true,"year":2021,"originalNumber":35,"source":"감염과 면역 족보_119.pdf · 2021년 35번 · PDF 48쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2021","35","기출"],"answerStatus":"source"},{"id":"past-2-64-2020-46","bank":"past","category":"eosinophilic-disorders","title":"2020년 46번","stem":"최근 비알레르기성 호산구 증가로 인한 천식 발생\n기전이 새롭게 규명되고 있다. 비특이적 자극을 받아 기\n도 상피에서 분비되고 innate lymphocyte를 활성화시키\n는 사이토카인 A는?\n① IL-3\n② IL-10\n③ IL-18\n④ IL-23\n⑤ IL-33","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2020-46-0.webp","./data/past-images/past-2-64-2020-46-1.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":46,"source":"감염과 면역 족보_119.pdf · 2020년 46번 · PDF 48쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","46","기출"],"answerStatus":"source"},{"id":"past-2-64-2020-47","bank":"past","category":"eosinophilic-disorders","title":"2020년 47번","stem":"다음 중 clonal eosinophilia 발병기전에 기초하여\n사용할 수 있는 효과적인 치료제는?\n① Interferon-α\n② Mepolizumab\n③ Hydroxyurea\n④ Imatinib\n⑤ Steroid","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2020-47-0.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":47,"source":"감염과 면역 족보_119.pdf · 2020년 47번 · PDF 48쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","47","기출"],"answerStatus":"source"},{"id":"past-2-64-2020-48","bank":"past","category":"eosinophilic-disorders","title":"2020년 48번","stem":"65세 남자가 우측 발 처짐과 이상 감각으로 내원하\n였다. 증상은 8개월 전부터 시작되었으며 6개월 전 시행\n한 외부 병원 검사 상 말초 혈액 호산구 수치가\n8600/ul로 증가한 것 이외 다른 이상은 찾지 못하였다.\n금일 검사한 말초 혈액 호산구 수치도 7200/ul으로 증\n가되어 있었다. 병력 청취상 호산구를 증가시킬 수 있는\n2차적인 원인은 불분명하였다. 가장 가능성이 큰 진단\n은?\n① Allergic bronchopulmonary aspergillosis\n② Chronic eosinophilic pneumonia\n③ Eosinophila myalgia syndrome\n④ Hypereosinophilic syndrome\n⑤ Eosinophilic leukemia","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-64-2020-48-0.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":48,"source":"감염과 면역 족보_119.pdf · 2020년 48번 · PDF 48쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","48","기출"],"answerStatus":"source"},{"id":"past-2-65-2025-3","bank":"past","category":"drug-allergy","title":"2025년 3번","stem":"다음은 원인 알레르겐을 찾기 위한 검사이다. 진단에\n가장 도움이 되는 환자는?\n① 고양이 옆에서 발생한 설사\n② 시계를 찬 피부에 발생한 습진\n③ 새우 섭취 직후 발생한 두드러기\n④ 아스피린 복용 직후 발생한 호흡곤란\n⑤ 페니실린 항생제 주사 1주일 후 발생한 열","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2025-3-0.webp","./data/past-images/past-2-65-2025-3-1.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":3,"source":"감염과 면역 족보_119.pdf · 2025년 3번 · PDF 48쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","3","기출"],"answerStatus":"source"},{"id":"past-2-65-2025-29","bank":"past","category":"drug-allergy","title":"2025년 29번","stem":"36세 여성이 만성 부비동염과 비용종 병력이 있다.\n나프록센 복용 40분 후 비폐색과 천명이 발생했으며 피\n부발진은 없었다. 이부프로펜 복용 후에도 유사 증상이\n두 차례 있었다. 가장 적절한 확진 검사는?\n① 아스피린 피부단자시험\n② 아스피린 특이 IgE (혈청)\n③ 아스피린 경구유발검사\n④ 아스피린 피내시험 (48-74시간 판독)\n⑤ 아스피린 첩포시험","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2025-29-0.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":29,"source":"감염과 면역 족보_119.pdf · 2025년 29번 · PDF 49쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","29","기출"],"answerStatus":"source"},{"id":"past-2-65-2025-46","bank":"past","category":"drug-allergy","title":"2025년 46번","stem":"일부 약물은 class I HLA의 항원결합부위에 직접 결\n합하여 그 화학적 특성을 변화시키고, 이로 인해 제시되\n는 자가 펩타이드의 레퍼토리가 바뀌어 비정상적 T세포\n활성화가 유발될 수 있다. 이 가설은?\n① Hapten model\n② Prohapten model\n③ HLA polymorphism\n④ Pharmacologic interaction model\n⑤ Altered peptide repertoire model","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2025-46-0.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":46,"source":"감염과 면역 족보_119.pdf · 2025년 46번 · PDF 49쪽 · 답안 64쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","46","기출"],"answerStatus":"source"},{"id":"past-2-65-2023-41","bank":"past","category":"drug-allergy","title":"2023년 41번","stem":"우리 몸의 면역세포가 약물을 항원으로 인식하게 되\n는 여러 모델 중, 약물과 HLA의 결합으로 HLA의 항원\n결합 부위의 화학적 특성이 변화되어 항원 제시 특이도\n가 변하여 비정상적으로 T세포가 활성화된 다는 가설은\n다음 중 무엇인가?\n① Hapten model\n② Prohapten model\n③ HLA polymorphism\n④ Pharmacologic interaction model\n⑤ Altered peptide repertoire model","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2023-41-0.webp","./data/past-images/past-2-65-2023-41-1.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":41,"source":"감염과 면역 족보_119.pdf · 2023년 41번 · PDF 49쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","41","기출"],"answerStatus":"source"},{"id":"past-2-65-2023-49","bank":"past","category":"drug-allergy","title":"2023년 49번","stem":"정상인들이 반응하지 않는 용량의 약물에 대한 반응\n으로 비면역학적 기전까지 포함하는 개념을 무엇이 라고\n하는가?\n① 약물 부작용\n② 약물 이상사례\n③ 약물 이상반응\n④ 약물 과민반응\n⑤ 약물 알레르기","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2023-49-0.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":49,"source":"감염과 면역 족보_119.pdf · 2023년 49번 · PDF 49쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","49","기출"],"answerStatus":"source"},{"id":"past-2-65-2022-2","bank":"past","category":"drug-allergy","title":"2022년 2번","stem":"43세 남자가 1일 전부터 시작된 가려운 발진으로 병\n원에 왔다. 4주 전 요산이 높다는 이야기를 듣고 알로퓨\n리놀을 복용하기 시작하였고, 5일 전부터는 삼차신경통이\n생겨 카바마제핀을 복용하기 시작하였다. 2일 전에 고열\n이 생기고 목이 아파서 이부프로펜을 복용하였다. 여행력\n등 다른 특이 사항은 없었다. 혈압 140/90mmHg, 맥박\n103회/분, 호흡수 20회/분, 체온 38.5도였다. 전신에\n발진이 관찰되었다.(사진) 진찰 소견과 검사실 소견은 다\n음과 같다. 이러한 반응과 가장 관련성이 잘 알려져 있는\n면역 관련 분자는?\n혈색소 12.9g/dL, 백혈구 23,600/mm^3(중성구\n55%, 림프구 28%, 호산구 17%), 아스파르테이트아\n미노산전달효소 140 U/L, 알라닌아미노산전달효소\n360 U/L\n① CTLA-4\n② TCR-V-α\n③ HLA-DQB1\n④ HLA-B5801\n⑤ allopurinol specific IgE","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2022-2-0.webp","./data/past-images/past-2-65-2022-2-1.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":2,"source":"감염과 면역 족보_119.pdf · 2022년 2번 · PDF 49쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","2","기출"],"answerStatus":"source"},{"id":"past-2-65-2022-29","bank":"past","category":"drug-allergy","title":"2022년 29번","stem":"67세 남자가 페니실린 주사를 맞고 5분 후 갑자기\n손 발 끝이 가렵고 식은 땀이 나면서 호흡이 답답한 증\n상이 발생하였다. 이 질환의 원인을 확인하기 위해 아래\n와 같은 검사를 통해 양성의 반응을 확인하였다. (검사는\n약물의 비자극 농도를 이용하여 시행하였다.) 이 검사에\n관여하는 면역반응에 가장 가까운 것은?\n① 보체에 의한 비만세포 활성화\n② p-I concept에 의한 T 세포 활성화\n③ IgE cross linking을 통한 비만세포 활성화\n④ MRGPRX 수용체를 통한 비만세포 활성화\n⑤ MHC-TCR 상호작용을 통한 T 세포 활성화","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2022-29-0.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":29,"source":"감염과 면역 족보_119.pdf · 2022년 29번 · PDF 50쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","29","기출"],"answerStatus":"source"},{"id":"past-2-65-2022-36","bank":"past","category":"drug-allergy","title":"2022년 36번","stem":"47세 여자가 근육통으로 에페리손(근육이완제)를 복\n용하고 5분 후 손끝부터 시작해 전신으로 퍼지는 가려운\n붉은 발진이 생기면서 호흡곤란을 호소하다가 기절하였\n다. 당시 혈압 40/10 mmHg, 맥박 150회/분, 호흡수\n5회/분, 체온 36.3℃였다. 이 증례와 같은 유형의 과민\n반응으로 인해 발생한 증례를 고르시오.\n① 채혈 도중 갑자기 얼굴이 하얗게 변하더니 기절했다.\n② 페니실린을 3일 간 먹고 피부에 구진반점이 발생하였\n다.\n③ 아스피린 100 mg 복용 후 갑자기 이명(tinnitus)이\n발생하였다.\n④ 새우를 먹던 도중 입이 간지럽고 몸에 두드러기가 발\n생하였다.\n⑤ 수혈 10분 후 갑자기 39℃의 열과 오한, 등의 통증\n을 호소하고 소변색이 붉어졌다.","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2022-36-0.webp","./data/past-images/past-2-65-2022-36-1.webp"],"choiceLabelsOnly":true,"year":2022,"originalNumber":36,"source":"감염과 면역 족보_119.pdf · 2022년 36번 · PDF 50쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2022","36","기출"],"answerStatus":"source"},{"id":"past-2-65-2021-40","bank":"past","category":"drug-allergy","title":"2021년 40번","stem":"32세 여자가 급성 인후염으로 아목시실린 항생제를\n복약 후 10분 만에 다음과 같은 피부 발진과 호흡곤란이\n발생하였다. 동일한 기전으로 발생한 증상은?\n① 찬 물에 닿자마자 발생한 두드러기\n② 사과 섭취 5분 후 발생한 입술 부종과 가려움\n③ 소염진통제 복용 10분 후 발생한 안검 부종\n④ 옻 닭 섭취 다음 날 발생한 전신 발진\n⑤ 메타콜린 기관지 유발검사 도중 발생한 호흡곤란","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2021-40-0.webp"],"choiceLabelsOnly":true,"year":2021,"originalNumber":40,"source":"감염과 면역 족보_119.pdf · 2021년 40번 · PDF 50쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2021","40","기출"],"answerStatus":"source"},{"id":"past-2-65-2021-51","bank":"past","category":"drug-allergy","title":"2021년 51번","stem":"45세 여자가 amoxicillin을 복용하고 10분 후 눈꺼\n풀이 붓고 목이 쉬어 응급실에 왔다. 3개월 전에도\ncefaclor를 복용하고 비슷한 증상을 경험하였다. 이러한\n현상을 설명하는데 가장 적합한 기전은 ?\n① p-i concept\n② Hapten theory\n③ Viral reactivation\n④ Structural similarity\n⑤ Direct mast cell activation","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2021-51-0.webp"],"choiceLabelsOnly":true,"year":2021,"originalNumber":51,"source":"감염과 면역 족보_119.pdf · 2021년 51번 · PDF 50쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2021","51","기출"],"answerStatus":"source"},{"id":"past-2-65-2021-52","bank":"past","category":"drug-allergy","title":"2021년 52번","stem":"47세 남자가 요통으로 진통소염제(naproxen)를 복용\n한 후 눈꺼풀이 심하게 부어 병원을 방문하였다. 1년 전\nibuprofen을 복용하고 비슷한 경험을 하였다. 혈압\n128/75mmHg, 맥박 78회/분, 호흡 12회/분, 체온\n36.5℃였다. 이러한 증상을 유발한 것과 가장 관련이 깊\n은 효소는?\n① LTC4 synthase\n② 5-lipoxygenase\n③ Phospholipase A2\n④ Cyclooxygenase-1\n⑤ Cyclooxygenase-2","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2021-52-0.webp","./data/past-images/past-2-65-2021-52-1.webp"],"choiceLabelsOnly":true,"year":2021,"originalNumber":52,"source":"감염과 면역 족보_119.pdf · 2021년 52번 · PDF 50쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2021","52","기출"],"answerStatus":"source"},{"id":"past-2-65-2021-56","bank":"past","category":"drug-allergy","title":"2021년 56번","stem":"53세 여자가 3일 전부터 시작된 피부발진으로 병원\n에 왔다. 4주 전 요산이 높다는 이야기를 듣고 알로퓨리\n놀을 복용하고 있고 10일 전부터 삼차신경통에 대해 카\n바마제핀 복용을 시작하였다. 여행력 등 다른 특이 사항\n은 없었다. 혈압 130/80mmHg, 맥박 100회/분, 호흡\n수 18회/분, 체온 38.9℃였다. 전신에 발진이 관찰되었\n다(사진) 진찰 소견과 검사실 소견은 다음과 같다. 치료\n는?\n혈색소 15.0g/dL, 백혈구 21,600/mm3(중성구\n25%, 림프구 28%, 호산구 37%) 아스파르테이트아\n미노전달효소 240U/L, 알라닌 아미노전달효소\n336U/L\n① 면역글로불린 정주\n② 항히스타민제\n③ 항류코트리엔제\n④ 고용량 스테로이드\n⑤ 항IgE 단클론항체 주사","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2021-56-0.webp"],"choiceLabelsOnly":true,"year":2021,"originalNumber":56,"source":"감염과 면역 족보_119.pdf · 2021년 56번 · PDF 51쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2021","56","기출"],"answerStatus":"source"},{"id":"past-2-65-2020-49","bank":"past","category":"drug-allergy","title":"2020년 49번","stem":"페니실린을 복용한 사람에게서 발진, 기절 등의 증\n상이 나타났다. 이에 대한 설명으로 옳은 것은?\n① 모든 베타락탐 계열의 항생제를 피하도록 한다.\n② 항생제로 반코마이신을 쓴다면 쓰기 전 선별적 피부\n검사가 필요하다.\n③ 항히스타민제와 전신 스테로이드로 전처치를 하면 페\n니실린을 투여할 수 있다.\n④ 페니실린에 대한 과민반응이 존재하므로, 어떤 경우에\n도 페니실린을 쓸 수 없음을 잘 교육시킨다.\n⑤ 페니실린 혈청 특이 IgE 검사와 페니실린에 대한 피\n부 검사가 진단에 도움이 된다.","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2020-49-0.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":49,"source":"감염과 면역 족보_119.pdf · 2020년 49번 · PDF 51쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","49","기출"],"answerStatus":"source"},{"id":"past-2-65-2020-50","bank":"past","category":"drug-allergy","title":"2020년 50번","stem":"43세 남작 1일 전부터 시작된 가려운 발진으로 내원\n하였다. 4주전 요산이 높다는 이야기를 듣고 알로퓨리놀\n을 복용하고 있고, 5일 전부터 삼차신경통에 대해 카바마\n제핀을 복용하기 시작하였다. 2일 전부터는 고열과 인후\n통으로 이부프로펜을 복용하고 시작했다. 여행력 등 다른\n특이 사항은 없었다. 혈압 140/90mmHg, 맥박 103회/\n분, 호흡수 20회/분, 체온 38.5도였다. 전신에 발진이\n관찰되었다.(사진) 진찰 소견과 검사실 소견은 다음과 같\n다. 원인은?\n진찰소견과 검사실 소견\n혈색소 14.9g/dL, 백혈구 25,300/mm^3(중성구\n55%, 림프구 28%, 호산구 17%), 아스파르테이트아\n미노산전달효소 140 U/L, 알라닌아미노산전달효소\n360 U/L\n① 알로퓨리놀\n② 카바마제핀\n③ 삼차신경통\n④ 이부프로펜\n⑤ 인플루엔자","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":1,"acceptedAnswers":[1],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2020-50-0.webp","./data/past-images/past-2-65-2020-50-1.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":50,"source":"감염과 면역 족보_119.pdf · 2020년 50번 · PDF 51쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ①\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","50","기출"],"answerStatus":"source"},{"id":"past-2-65-2020-51","bank":"past","category":"drug-allergy","title":"2020년 51번","stem":"43세 여자가 감기약을 먹고 30분만에 눈커풀이 붓\n고 목이 쉬어 응급실에 왔다. 3개월 전에는 정형외과약을\n먹고 전신에 두드러기가 나서 응급조치를 받은 적이 있\n다. 복용한 약제는 다음과 같다. 다음 중 가장 반응이 잘\n일어날 것 같은 검사법은?\n감기약 : Ibuprofen, Cefaclor, Dextromethorphan,\nGuaifenesin, Triprolidine\n정형외과약 : Acetazolac, Eperisone, Rantidine,\nStreptokinase\n① Penicillin을 피내주사한다.\n② Ibuprofen을 피내주사한다.\n③ 아스피린 경구유발검사\n④ Cefaclor에 대해 혈청 IgE 검사를 한다.\n⑤ Acetazolac에 대해 혈청 IgE 검사를 한다.","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2020-51-0.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":51,"source":"감염과 면역 족보_119.pdf · 2020년 51번 · PDF 52쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","51","기출"],"answerStatus":"source"},{"id":"past-2-65-2020-56","bank":"past","category":"drug-allergy","title":"2020년 56번","stem":"급성 신우 신염으로 3세대 세팔로스포린 항생제 치\n료를 받던 중, 10주 째에 아래 그림과 같은 피부 병변이\n발생하였다. 다음 중 동일한 기전으로 생긴 증상은?\n① 찬 물에 닿자마자 발생한 두드러기\n② 소염항생제 복용 10분 후 발생한 안검부종\n③ 라텍스 장갑 착용 3분 후 발생한 아나필락시스\n④ 메타콜린 기관지 과민성 유발검사\n⑤ 구리반지를 낀 후 2주 뒤에 발생한 진물이 흐르는 피\n부 병변","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-65-2020-56-0.webp"],"choiceLabelsOnly":true,"year":2020,"originalNumber":56,"source":"감염과 면역 족보_119.pdf · 2020년 56번 · PDF 52쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2020","56","기출"],"answerStatus":"source"},{"id":"past-2-62-2025-20","bank":"past","category":"cancer-immunity","title":"2025년 20번","stem":"생체내에서 암에대한 면역감시 현상으로 보기 어려\n운 것은 ?\n① 종양 조직내 림프구 수의 증가\n② 종양 특이적인 T 림프구의 존재\n③ 원발암의 수술적 제거후 타 장기에서 전이암의 증가\n④ HIV 감염된 환자에서 암 빈도 증가\n⑤ 암근처 림프절에 림프구 수의 증가","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-62-2025-20-0.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":20,"source":"감염과 면역 족보_119.pdf · 2025년 20번 · PDF 52쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","20","기출"],"answerStatus":"source"},{"id":"past-2-62-2025-24","bank":"past","category":"cancer-immunity","title":"2025년 24번","stem":"68세 전이성 비소세포폐암 환자가 Pembrolizumab\n치료 7주기 후 광범위한 maculopapular rash가 발생하\n였다. 이러한 면역관련 피부이상반응(immune-related\nskin adverse event)의 발생 기전으로 가장 적절한 것\n은?\n① 보체의존성세포독성(complement-dependent\ncytotoxicity)\n② 피부 세포의 PD-L1 과발현\n③ 정상 피부조직에 대한 자가반응성 T-세포 활성화\n④ 힝체의존세포독성(antibody-dependent cellular\ncytotoxicity)\n⑤ IgE-매개 즉시형 알레르기 반응","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":3,"acceptedAnswers":[3],"answerMode":"single","scanImages":["./data/past-images/past-2-62-2025-24-0.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":24,"source":"감염과 면역 족보_119.pdf · 2025년 24번 · PDF 52쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ③\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","24","기출"],"answerStatus":"source"},{"id":"past-2-62-2025-40","bank":"past","category":"cancer-immunity","title":"2025년 40번","stem":"암이 임상적으로 발견되기 까지 종양 미세환경에서\n암세포와 면역세포간의 상호 작용을 시차 순으로 가장\n잘 설명한 것은 ?\n① Emergence, Equilibrium, Extinction\n② Encounter, Engagement, Evasion\n③ Exposure, Escalation, Eradication\n④ Engagement, Endurance, Exhaustion\n⑤ Elimination, Equilibrium, Escape","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-62-2025-40-0.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":40,"source":"감염과 면역 족보_119.pdf · 2025년 40번 · PDF 52쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","40","기출"],"answerStatus":"source"},{"id":"past-2-62-2025-41","bank":"past","category":"cancer-immunity","title":"2025년 41번","stem":"말초성 관용 (peripheral tolerance)에서 중요한 수\n용체로 T-세포의 표면에 표현하는 면역 관문 (immune\ncheckpoint) 역할을 하며 다양한 종양에서 치료제로 승\n인된 것은?\n① CD273 (B7-DC)\n② CD279 (PD-1)\n③ CD152 (CTLA-4)\n④ CD274 (B7-H1)\n⑤ JAK2","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-62-2025-41-0.webp","./data/past-images/past-2-62-2025-41-1.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":41,"source":"감염과 면역 족보_119.pdf · 2025년 41번 · PDF 52쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","41","기출"],"answerStatus":"source"},{"id":"past-2-62-2025-53","bank":"past","category":"cancer-immunity","title":"2025년 53번","stem":"다음 중 아래 환자에서 관찰된 면역회피 기전으로\n올바른 것은?\n25세 남성 환자가 B형 간염 바이러스(HBV)에 지속\n적으로 감염되어 만성 간염 진단을 받았다. 검사 결\n과, 환자의 간 조직에서는 MHC 클래스 I 분자의 발\n현이 크게 감소되어 있었으며, 바이러스 유전체 분석\n에서 표면 항원(HBsAg)의 변이가 다수 확인되었다.\n① 항원 대변이\n② 항원 제공 억제\n③ 대식세포 억제\n④ 조절 T 림프구 억제\n⑤ 골수유래 면역억제 세포 활성화","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":2,"acceptedAnswers":[2],"answerMode":"single","scanImages":["./data/past-images/past-2-62-2025-53-0.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":53,"source":"감염과 면역 족보_119.pdf · 2025년 53번 · PDF 53쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ②\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","53","기출"],"answerStatus":"source"},{"id":"past-2-62-2025-58","bank":"past","category":"cancer-immunity","title":"2025년 58번","stem":"T-세포 이중특이항체는 CD3 및 종양 항원을 동시\n에 인지하여 T-세포가 종양을 직접 공격하도록 유도한\n다. T-세포 이중특이항체 중 악성 B-세포림프종 치료를\n위해 표적으로 하는 B-세포 항원은?\n① CD19\n② DLL4\n③ HER2\n④ EGFR\n⑤ PD-L1","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":1,"acceptedAnswers":[1],"answerMode":"single","scanImages":["./data/past-images/past-2-62-2025-58-0.webp"],"choiceLabelsOnly":true,"year":2025,"originalNumber":58,"source":"감염과 면역 족보_119.pdf · 2025년 58번 · PDF 53쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ①\n","origin":"족보 기출","difficulty":"미지정","tags":["2025","58","기출"],"answerStatus":"source"},{"id":"past-2-62-2023-14","bank":"past","category":"cancer-immunity","title":"2023년 14번","stem":"전림샘암 백신인 sipuleucel-T와 가장 유사한 형태\n의 항암제나 요법을 가지고 연구하거나 치료한 내용에\n해당하는 것은?\n① CD80 유전자를 발현시킨 흑색종세포를 방사선 조사\n한 후 해당 세포를 주사한 정상마우스는 악성흑 색종 세\n포를 접종해도 높은 확률로 흑색종이 발생하지 않는다.\n② 지미 카터 전 미국 대통령에게 발병한 흑색종이 간에\n이어 뇌까지 전이되었으나 PD-1을 타겟으로 하는 면역\n항암제를 주사하고 완치되었다.\n③ 전이성 유방암을 지닌 여성 중 neu 유전자에 의해\nHER2 발현이 증가할 경우 항 HER2 단일클론 항 체를\n주입하여 유방암을 치료하였다.\n④ 대장암으로 내원한 환자에 방사선 조사를 통해 암 크\n기를 일정 수준으로 줄인 후 외과적인 수술로 해당 부위\n를 제거하고 DNA 합성과 세포 분열을 억제하는 화학요\n법을 시행한다.\n⑤ 진행성 종양 성장이 있는 동물로부터 얻어진 혈청은\n시험관 내에서 CTL에 의한 세포용해를 방해하 지만 종\n양이 퇴행 중인 동물로부터 얻어진 혈청은 CTL에 의한\n세포 용해반응을 방해하지 않는다.","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":1,"acceptedAnswers":[1],"answerMode":"single","scanImages":["./data/past-images/past-2-62-2023-14-0.webp","./data/past-images/past-2-62-2023-14-1.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":14,"source":"감염과 면역 족보_119.pdf · 2023년 14번 · PDF 53쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ①\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","14","기출"],"answerStatus":"source"},{"id":"past-2-62-2023-34","bank":"past","category":"cancer-immunity","title":"2023년 34번","stem":"전이성 비소세포폐암으로 진단받은 68세 남자 환자\n가 면역관문억제제 (immune checkpoint inhibitor) 치\n료받았다. 치료 시작 후 8주에 아래 그림과 같은 피부\n발진이 발생하였다. 다음 중 이러한 면역관련부작용이 발\n생하였을 때, 부작용을 줄이기 위해 주로 사용되는 약제\n는?\n① Lorazepam\n② Doxycycline\n③ IVIG\n④ Corticosteroid\n⑤ Methotrexate","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":4,"acceptedAnswers":[4],"answerMode":"single","scanImages":["./data/past-images/past-2-62-2023-34-0.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":34,"source":"감염과 면역 족보_119.pdf · 2023년 34번 · PDF 53쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ④\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","34","기출"],"answerStatus":"source"},{"id":"past-2-62-2023-36","bank":"past","category":"cancer-immunity","title":"2023년 36번","stem":"다음 중 암의 특징에 해당하지 않는 것은?\n① 세포사멸에 저항\n② DNA의 변형\n③ 신생혈관 유도\n④ 면역파괴로 부터의 회피\n⑤ 급성 염증 유발","options":["1번 보기","2번 보기","3번 보기","4번 보기","5번 보기"],"answer":5,"acceptedAnswers":[5],"answerMode":"single","scanImages":["./data/past-images/past-2-62-2023-36-0.webp"],"choiceLabelsOnly":true,"year":2023,"originalNumber":36,"source":"감염과 면역 족보_119.pdf · 2023년 36번 · PDF 53쪽 · 답안 65쪽","explanation":"족보 답안표 기준 정답: ⑤\n","origin":"족보 기출","difficulty":"미지정","tags":["2023","36","기출"],"answerStatus":"source"}];
